pub fn field_length_invalid_exception(
    field_name: &str,
    actual_length: i64,
    min_length: Option<i64>,
    max_length: Option<i64>,
) -> PhpException {
    let first_part: String;
    if let Some(min_length) = min_length
        && let Some(max_length) = max_length
    {
        first_part = format!(
            "Field {} must be between {} and {} characters in length",
            field_name, min_length, max_length
        );
    } else if let Some(max_length) = max_length {
        first_part = format!(
            "Field {} must be at most {} characters in length",
            field_name, max_length
        );
    } else if let Some(min_length) = min_length {
        first_part = format!(
            "Field {} must be at least {} characters in length",
            field_name, min_length
        );
    } else {
        first_part = format!("Field {} length is invalid", field_name);
    }
    let message = format!("{}. Length given is {}", first_part, actual_length);
    return PhpException::new("App\\Exceptions\\FieldLengthInvalidException", &message, 0);
}

pub fn role_already_exists_exception(message: &str) -> PhpException {
    return PhpException::new("App\\Exceptions\\RoleAlreadyExistsException", message, 409);
}

pub fn check(name: &str) -> Result<String, PhpException> {
    if (name.len() as i64) < 3 {
        return Err(field_length_invalid_exception(
            name,
            name.len() as i64,
            Some(3),
            Some(10),
        ));
    }
    if name == "admin" {
        return Err(role_already_exists_exception("Role already exists"));
    }
    if name == "ghost" {
        return Err(PhpException::new(
            "App\\Exceptions\\MissingRoleException",
            "no ghost",
            404,
        ));
    }
    return Ok(name.to_string());
}

